SELECT count(*) AS total, count(*) FILTER (WHERE admin.finding.severity = 'error') AS errors, count(*) FILTER (WHERE admin.finding.severity = 'warning') AS warnings, count(*) FILTER (WHERE admin.finding.severity = 'info') AS info, count(*) FILTER (WHERE CAST((admin.finding.metadata['finding'] ->> 'priority') AS INTEGER) <= 2 OR (admin.finding.metadata['finding']['priority_reasons'] @> '["published_soon"]'::jsonb)) AS urgent, admin.finding.rule 
FROM admin.finding 
WHERE admin.finding.status != 'resolved' GROUP BY admin.finding.rule;

SELECT count(*) AS count_1 
FROM admin.finding 
WHERE admin.finding.status != 'resolved';

SELECT admin.check_run.id, admin.check_run.started_at, admin.check_run.finished_at, admin.check_run.status, admin.check_run.rule_count, admin.check_run.finding_count, admin.check_run.worker_id, admin.check_run.lease_until 
FROM admin.check_run ORDER BY admin.check_run.started_at DESC, admin.check_run.id DESC 
 LIMIT 1;

SELECT count(*) AS count_1 
FROM admin.finding 
WHERE admin.finding.status != 'resolved' AND admin.finding.severity = 'error';

SELECT v.uuid id,
        (SELECT count(*) FROM uranus.space s WHERE s.venue_uuid=v.uuid) spaces
        FROM uranus.venue v WHERE v.uuid=ANY(ARRAY['00000000-0000-0000-0000-000000000014']::UUID[]);

SELECT admin.finding.entity_id, count(*) AS count_1 
FROM admin.finding 
WHERE admin.finding.entity_type = 'venue' AND admin.finding.entity_id IN ('00000000-0000-0000-0000-000000000014') AND admin.finding.status != 'resolved' GROUP BY admin.finding.entity_id;

SELECT admin.record_mark.entity_key, count(*) AS count_1 
FROM admin.record_mark 
WHERE admin.record_mark.entity_type = 'venue' AND admin.record_mark.entity_key IN ('00000000-0000-0000-0000-000000000014') GROUP BY admin.record_mark.entity_key;
